#include <vector>
#include <algorithm>

class Solution {
public:
    int maxEqualAdjacentPairs(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;

        int base = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (nums[i] == nums[i + 1]) base++;
        }

        int max_gain = 0;
        for (int i = 0; i < n; ++i) {
            int old_m = 0;
            if (i > 0 && nums[i] == nums[i - 1]) old_m++;
            if (i < n - 1 && nums[i] == nums[i + 1]) old_m++;

            std::vector<int> cands;
            if (i > 0) cands.push_back(nums[i - 1]);
            if (i < n - 1) cands.push_back(nums[i + 1]);

            for (int cand : cands) {
                int new_m = 0;
                if (i > 0 && cand == nums[i - 1]) new_m++;
                if (i < n - 1 && cand == nums[i + 1]) new_m++;
                max_gain = std::max(max_gain, new_m - old_m);
            }
        }
        return base + max_gain;
    }
};

class Solution {
    public int maxEqualAdjacentPairs(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;

        int base = 0;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) base++;
        }

        int maxGain = 0;
        for (int i = 0; i < n; i++) {
            int oldM = 0;
            if (i > 0 && nums[i] == nums[i - 1]) oldM++;
            if (i < n - 1 && nums[i] == nums[i + 1]) oldM++;

            int[] cands = new int[]{i > 0 ? nums[i - 1] : -1, i < n - 1 ? nums[i + 1] : -1};
            for (int cand : cands) {
                if (cand == -1) continue;
                int newM = 0;
                if (i > 0 && cand == nums[i - 1]) newM++;
                if (i < n - 1 && cand == nums[i + 1]) newM++;
                maxGain = Math.max(maxGain, newM - oldM);
            }
        }
        return base + maxGain;
    }
}

